/*! Lightweight offline Markdown parser tailored for Kitana Builder */
(function(global){function escapeHtml(str){return str.replace(/[&<>"']/g,function(ch){return({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;','\'':'&#39;'}[ch]);});}function parseInline(text){return text.replace(/`([^`]+)`/g,'<code>$1</code>').replace(/\*\*([^*]+)\*\*/g,'<strong>$1</strong>').replace(/\*([^*]+)\*/g,'<em>$1</em>').replace(/\[(.*?)\]\((.*?)\)/g,'<a href="$2">$1</a>');}function parse(md){const lines=md.split(/\r?\n/);const html=[];let inList=false;lines.forEach(line=>{if(/^\s*$/.test(line)){if(inList){html.push('</ul>');inList=false;}return;}if(/^#/.test(line)){if(inList){html.push('</ul>');inList=false;}const level=line.match(/^#+/)[0].length;const content=parseInline(line.replace(/^#+\s*/,''));html.push(`<h${level}>${content}</h${level}>`);return;}if(/^[-*]\s+/.test(line)){if(!inList){html.push('<ul>');inList=true;}const item=parseInline(line.replace(/^[-*]\s+/,''));html.push(`<li>${item}</li>`);return;}if(/^>\s*/.test(line)){if(inList){html.push('</ul>');inList=false;}html.push(`<blockquote>${parseInline(line.replace(/^>\s*/,''))}</blockquote>`);return;}if(/^```/.test(line)){if(html.length && html[html.length-1].startsWith('<pre')){html.push('</code></pre>');return;}html.push('<pre><code>');return;}if(html.length && html[html.length-1]==='<pre><code>'){html.push(escapeHtml(line)+'\n');return;} if(inList){html.push('</ul>');inList=false;}html.push(`<p>${parseInline(line)}</p>`);});if(inList){html.push('</ul>');}return html.join('');}global.marked={parse};})(this);
